WITH cleaned AS (SELECT id, supplier_name, country, city, rating, CASE WHEN country IN ('US', 'DE') THEN 'Tier 1' ELSE 'Other' END AS country_group FROM suppliers WHERE city IS NOT NULL), cleaned_suppliers AS (SELECT *, TRIM(country) AS clean_country FROM cleaned WHERE city = 'London'), metrics AS (SELECT id, supplier_name, country, city, rating, country_group, clean_country, SUM(rating) OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_rating, NTILE(10) OVER (PARTITION BY country ORDER BY rating, id) AS rating_bucket FROM cleaned_suppliers) SELECT id, supplier_name, country, country_group, clean_country, running_rating, CASE WHEN supplier_name RLIKE '^(Global Supply|Lion City Imports)$' THEN 'EXTENDED' WHEN supplier_name RLIKE '^(Siam Parts Co|Tokyo Traders)$' THEN 'PRIORITY' ELSE 'GROUP_A' END AS supplier_name_zone FROM metrics ORDER BY id DESC NULLS FIRST LIMIT 20
